import { fileURLToPath } from 'node:path'
import { dirname } from 'node:path'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import { VitePWA } from 'vite-plugin-pwa'
import { defineConfig } from 'vite'

export default defineConfig({
  plugins: [
    react(),
    tailwindcss(),
    VitePWA({
      registerType: 'autoUpdate',
      // Statische Dateien aus public/, die nicht über die Manifest-Icons
      // mit in den Precache kämen (Manifest-Icons werden automatisch precached).
      includeAssets: ['favicon.svg', 'apple-touch-icon.png'],
      manifest: {
        id: '/',
        name: 'Fokusrad',
        short_name: 'Fokusrad',
        description:
          'Ein 5-Minuten-Gedanken-Shift: Fülle acht Segmente rund um dein Zielgefühl und bringe deine Stimmung sanft in Bewegung.',
        lang: 'de',
        theme_color: '#f6f1e8',
        background_color: '#f6f1e8',
        display: 'standalone',
        orientation: 'portrait',
        start_url: '/',
        scope: '/',
        categories: ['health', 'lifestyle', 'productivity'],
        icons: [
          {
            src: '/icons/icon-192.png',
            sizes: '192x192',
            type: 'image/png',
            purpose: 'any'
          },
          {
            src: '/icons/icon-512.png',
            sizes: '512x512',
            type: 'image/png',
            purpose: 'any'
          },
          {
            src: '/icons/icon-maskable-512.png',
            sizes: '512x512',
            type: 'image/png',
            purpose: 'maskable'
          },
          {
            src: '/icons/icon.svg',
            sizes: 'any',
            type: 'image/svg+xml',
            purpose: 'any'
          }
        ]
      },
      workbox: {
        globPatterns: ['**/*.{js,css,html,ico,png,svg,webmanifest}'],
        navigateFallback: '/index.html',
        cleanupOutdatedCaches: true,
        maximumFileSizeToCache: 4 * 1024 * 1024,
        runtimeCaching: [
          {
            // Alles läuft lokal: externe Ressourcen gibt es nicht,
            // aber falls doch (z. B. Fonts) CacheFirst mit TTL.
            urlPattern: /\.(?:png|jpg|jpeg|svg|webp|woff2?)$/,
            handler: 'CacheFirst',
            options: {
              cacheName: 'fokusrad-images-v1',
              expiration: {
                maxEntries: 30,
                maxAgeSeconds: 30 * 24 * 60 * 60
              },
              cacheableResponse: {
                statuses: [0, 200]
              }
            }
          }
        ]
      },
      devOptions: {
        // PWA-Features (Service Worker) auch während `npm run dev` testen.
        enabled: false
      }
    })
  ],
  server: {
    // Damit die App auch von echten Smartphones im LAN erreichbar ist.
    host: true
  }
})

@import "tailwindcss";

/* Klassen-basierter Dark Mode (.dark auf <html>) für Tailwind-v4-Varianten. */
@custom-variant dark (&:where(.dark, .dark *));

/*
  „Morgenfluss"-Palette
  Light: warme Sandtöne + Salbei/Teal
  Dark:  tiefer Slate-Teal + warmes Creme
  Alle Text-/Hintergrund-Kombos sind nach WCAG AA abgeglichen.
*/
:root {
  --bg: #f6f1e8;
  --bg-soft: #efe7d9;
  --surface: #fcfaf5;
  --surface-2: #f0ead d;
  --ink: #2b3a36;
  --ink-2: #56685f;
  --ink-3: #64756c;
  --accent: #2e7d6d;
  --accent-strong: #246053;
  --accent-ink: #f7fbf6;
  --sage: #8fae94;
  --sand: #e3d7c0;
  --line: #e0d7c3;
  --danger: #a85440;
  --shadow: 32 43 39; /* RGB für getönte Schatten */

  --mood-1: #b26049;
  --mood-2: #bb8452;
  --mood-3: #9a9a5f;
  --mood-4: #6f9f6e;
  --mood-5: #2e7d6d;
  --mood-num-1: #fdf8f3;
  --mood-num-2: #33261a;
  --mood-num-3: #2e2e1c;
  --mood-num-4: #1d2b1c;
  --mood-num-5: #f7fbf6;

  --wheel-empty: #eae2d2;
  --wheel-1: #2c7a6b;
  --wheel-2: #378670;
  --wheel-3: #479176;
  --wheel-4: #5a9b7a;
  --wheel-5: #6ca37e;
  --wheel-6: #7eab84;
  --wheel-7: #8fb28b;
  --wheel-8: #a0ba92;

  --seg-num: #f4efe4;
  --center-ink: #2b3a36;

  color-scheme: light;
}

.dark {
  --bg: #131c1a;
  --bg-soft: #182420;
  --surface: #1d2b27;
  --surface-2: #24332e;
  --ink: #ece7da;
  --ink-2: #a8b5a9;
  --ink-3: #8a9a8e;
  --accent: #67bda6;
  --accent-strong: #7ecbbc;
  --accent-ink: #10201b;
  --sage: #7d9c85;
  --sand: #3b3a2e;
  --line: #2e3d37;
  --danger: #d98a72;
  --shadow: 0 0 0;

  --mood-1: #d98a72;
  --mood-2: #d9a06b;
  --mood-3: #c9c178;
  --mood-4: #96c28f;
  --mood-5: #6fc7a8;
  --mood-num-1: #2b150e;
  --mood-num-2: #332008;
  --mood-num-3: #2e2a10;
  --mood-num-4: #16260f;
  --mood-num-5: #0c261d;

  --wheel-empty: #263530;
  --wheel-1: #4f9c88;
  --wheel-2: #5ca38d;
  --wheel-3: #69aa90;
  --wheel-4: #77b093;
  --wheel-5: #85b694;
  --wheel-6: #93bc92;
  --wheel-7: #a1c193;
  --wheel-8: #afc894;

  --seg-num: #15201d;
  --center-ink: #ece7da;

  color-scheme: dark;
}

/* CSS-Variablen als Tailwind-Farben abbilden (bg-bg, text-ink, border-line, …).
   `inline` sorgt dafür, dass die Utilities die Laufzeit-Variablen referenzieren
   und so auf den .dark-Wechsel reagieren. */
@theme inline {
  --color-bg: var(--bg);
  --color-bg-soft: var(--bg-soft);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-accent: var(--accent);
  --color-accent-strong: var(--accent-strong);
  --color-accent-ink: var(--accent-ink);
  --color-sage: var(--sage);
  --color-sand: var(--sand);
  --color-line: var(--line);
  --color-danger: var(--danger);

  --font-sans:
    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue",
    Arial, "Noto Sans", sans-serif;
}

/* ------------------------------------------------------------------ */
/* mobile-native-Baseline                                              */
/* ------------------------------------------------------------------ */

html {
  -webkit-tap-highlight-color: transparent;
  -webkit-text-size-adjust: 100%;
  overscroll-behavior: none;
}

body {
  margin: 0;
  overscroll-behavior: none;
  background-color: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

/* iOS zoomt bei Fokus, wenn das Eingabefeld < 16 px groß ist. */
input,
textarea,
select {
  font-size: 16px;
}

/* Kein Double-Tap-Zoom-Verzug auf steuerelementen. */
button,
a,
[role="button"],
.tappable {
  touch-action: manipulation;
}

/* Keine Textauswahl / Long-Press-Callout auf Bedienelementen. */
button,
[role="button"],
.chip,
.tab {
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
}

/* App-Shell: folgt dem sichtbaren Viewport (dvh), Fallback für alte Browser. */
.app-shell {
  min-height: 100vh;
  min-height: 100dvh;
}

/* Safe-Area-Auslassungen (viewport-fit=cover ist in index.html gesetzt). */
.safe-top {
  padding-top: env(safe-area-inset-top, 0px);
}
.safe-bottom {
  padding-bottom: env(safe-area-inset-bottom, 0px);
}

/* Drück-Feedback statt Browser-Flash (100–160 ms, ease-out). */
.press {
  transition:
    transform 120ms ease-out,
    background-color 120ms ease-out,
    border-color 120ms ease-out,
    opacity 120ms ease-out;
}
.press:active {
  transform: scale(0.97);
}

/* Hover-Styles nur für echte Pointer-Geräte (Tailwinds `hover:` kompiliert
   bereits zu `@media (hover: hover)` – hier für handgeschriebene Klassen). */
@media (hover: hover) and (pointer: fine) {
  .btn-primary:hover {
    background-color: var(--accent-strong);
  }
  .btn-ghost:hover {
    background-color: color-mix(in srgb, var(--accent) 10%, transparent);
  }
  .press:hover {
    opacity: 0.88;
  }
}

/* ------------------------------------------------------------------ */
/* Gemeinsame Bausteine                                               */
/* ------------------------------------------------------------------ */

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 48px;
  border-radius: 9999px;
  background-color: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
  font-size: 16px;
  padding: 0 1.5rem;
  border: none;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    0 10px 24px -12px rgb(var(--shadow) / 0.55);
  cursor: pointer;
}
.btn-primary:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: none;
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 48px;
  border-radius: 9999px;
  background-color: transparent;
  color: var(--ink);
  font-weight: 500;
  font-size: 16px;
  padding: 0 1.25rem;
  border: 1px solid var(--line);
  cursor: pointer;
}

.card {
  background-color: var(--surface);
  border: 1px solid var(--line);
  border-radius: 1.5rem;
  box-shadow: 0 14px 34px -22px rgb(var(--shadow) / 0.5);
}

.field {
  width: 100%;
  min-height: 48px;
  border-radius: 1rem;
  background-color: var(--surface-2);
  border: 1px solid transparent;
  color: var(--ink);
  padding: 0.875rem 1rem;
  font-size: 16px;
  line-height: 1.5;
  transition: border-color 150ms ease, background-color 150ms ease;
}
.field::placeholder {
  color: var(--ink-3);
  opacity: 1;
}
.field:focus {
  outline: none;
  border-color: var(--accent);
  background-color: var(--surface);
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Sanfte Segment-Füllung im SVG-Rad. */
.wheel-segment {
  transition:
    fill 500ms ease,
    opacity 500ms ease;
}
.wheel-center {
  transition: fill 500ms ease, stroke 500ms ease;
}

/* Ruhiger Einblend-Übergang zwischen Ansichten. */
@keyframes rise-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.rise-in {
  animation: rise-in 320ms ease-out both;
}

@keyframes pop-in {
  0% {
    opacity: 0;
    transform: scale(0.86);
  }
  70% {
    transform: scale(1.03);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}
.pop-in {
  animation: pop-in 420ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

@media (prefers-reduced-motion: reduce) {
  .rise-in,
  .pop-in,
  .wheel-segment,
  .wheel-center,
  .press {
    animation: none;
    transition: none;
  }
}

/** Anzahl der Segmente eines Fokusrads – fest durch die Methode vorgegeben. */
export const SEGMENT_COUNT = 8

/** Dauer eines Fokusrads in Sekunden (5 Minuten). */
export const WHEEL_DURATION_SECONDS = 5 * 60

/** Gewünschte Darstellung des Themas. */
export type ThemePreference = 'light' | 'dark' | 'system'

/**
 * Ein Fokusrad.
 * `completedAt === null` bezeichnet eine laufende (noch offene) Session,
 * die als Entwurf in `localStorage` zwischengespeichert wird.
 */
export interface FocusWheel {
  id: string
  /** ISO-Zeitstempel der Eröffnung. */
  createdAt: string
  /** ISO-Zeitstempel des Abschlusses, `null` solange die Session läuft. */
  completedAt: string | null
  /** Ausgangsgedanke / aktuelles Gefühl (was gerade stört oder drückt). */
  startThought: string
  /** Zielgedanke / Wunschgefühl (steht im Zentrum des Rads). */
  targetThought: string
  /** Start-Stimmung auf einer Skala von 1 bis 5. */
  startMood: number
  /** End-Stimmung auf einer Skala von 1 bis 5, `null` vor dem Abschluss. */
  endMood: number | null
  /** Die acht überbrückenden, entlastenden Sätze (Segment 1 bis 8). */
  segments: string[]
}

/** Gesamter, persistierter Zustand der App. */
export interface AppState {
  /** Versionsnummer der Speicherschicht (Migrationsschutz). */
  version: number
  theme: ThemePreference
  /** Abgeschlossene Fokusräder, neueste zuerst. */
  wheels: FocusWheel[]
  /** Laufende Session bzw. `null`. */
  draft: FocusWheel | null
}

/** Kurz-Labels für die 5-Punkte-Stimmungsskala (Index 0 = Stimmung 1). */
export const MOOD_LABELS = [
  'stark belastet',
  'angespannt',
  'neutrale Mitte',
  'ausgeglichen',
  'sehr ruhig'
] as const

/** Stellt sicher, dass eine Stimmung immer im Bereich 1–5 liegt. */
export function clampMood(value: unknown): number {
  const n = typeof value === 'number' ? Math.round(value) : Number(value)
  if (!Number.isFinite(n)) return 3
  return Math.min(5, Math.max(1, n))
}

/** Zählt gefüllte Segmente eines Rads. */
export function filledSegmentCount(wheel: Pick<FocusWheel, 'segments'>): number {
  return wheel.segments.filter((s) => s.trim().length > 0).length
}

/** Erzeugt eine frische, noch leere Session. */
export function createDraft(
  startThought: string,
  targetThought: string,
  startMood: number
): FocusWheel {
  const now = new Date().toISOString()
  return {
    id: newWheelId(),
    createdAt: now,
    completedAt: null,
    startThought: startThought.trim(),
    targetThought: targetThought.trim(),
    startMood: clampMood(startMood),
    endMood: null,
    segments: Array<string>(SEGMENT_COUNT).fill('')
  }
}

/** Erzeugt eine eindeutige Kennung (mit Fallback für ältere Browser). */
export function newWheelId(): string {
  try {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return crypto.randomUUID()
    }
  } catch {
    /* Fallback unten */
  }
  return `wheel-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`
}

import type { AppState, FocusWheel, ThemePreference } from './types'
import { SEGMENT_COUNT, clampMood } from './types'

/** Versionsnummer der Speicherschicht. */
export const STATE_VERSION = 1

/** Schlüssel des versionierten `localStorage`-Zustands. */
export const STORAGE_KEY = `fokusrad:v${STATE_VERSION}:state`

/** Obergrenzen für Textfelder – schützt gegen kaputt gewordene/gigantische Einträge. */
const LIMITS = {
  startThought: 1000,
  targetThought: 500,
  segment: 400
} as const

export function createEmptyState(): AppState {
  return {
    version: STATE_VERSION,
    theme: 'system',
    wheels: [],
    draft: null
  }
}

/* ------------------------------------------------------------------ */
/* Sanitisierung: Ungültige gespeicherte Daten dürfen die App nie       */
/* zum Absturz bringen – alles Unerwartbare wird still bereinigt.      */
/* ------------------------------------------------------------------ */

function sanitizeText(value: unknown, limit: number): string {
  if (typeof value !== 'string') return ''
  const trimmed = value.trim()
  return trimmed.length > limit ? trimmed.slice(0, limit) : trimmed
}

function sanitizeIsoDate(value: unknown): string | null {
  if (typeof value !== 'string') return null
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? null : value
}

function sanitizeTheme(value: unknown): ThemePreference {
  return value === 'light' || value === 'dark' || value === 'system' ? value : 'system'
}

function sanitizeWheel(raw: unknown): FocusWheel | null {
  if (typeof raw !== 'object' || raw === null) return null
  const record = raw as Record<string, unknown>

  if (typeof record.id !== 'string' || record.id.length === 0) return null

  const rawSegments = Array.isArray(record.segments) ? record.segments : []
  const segments: string[] = []
  for (let i = 0; i < SEGMENT_COUNT; i++) {
    segments.push(sanitizeText(rawSegments[i] ?? '', LIMITS.segment))
  }

  const completedAt = sanitizeIsoDate(record.completedAt)
  const createdAt = sanitizeIsoDate(record.createdAt) ?? new Date().toISOString()

  return {
    id: record.id.slice(0, 128),
    createdAt,
    completedAt,
    startThought: sanitizeText(record.startThought, LIMITS.startThought),
    targetThought: sanitizeText(record.targetThought, LIMITS.targetThought),
    startMood: clampMood(record.startMood),
    endMood: completedAt !== null ? clampMood(record.endMood) : null,
    segments
  }
}

function sanitizeWheels(raw: unknown): FocusWheel[] {
  if (!Array.isArray(raw)) return []
  const wheels: FocusWheel[] = []
  for (const entry of raw) {
    const wheel = sanitizeWheel(entry)
    if (wheel !== null) wheels.push(wheel)
  }
  // Neueste zuerst.
  return wheels.sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1))
}

/**
 * Lädt den App-Zustand aus `localStorage`.
 * Fehlt, ist kaputt oder eine unbekannte Version: ein leerer, gültiger
 * Zustand wird zurückgegeben (bestefforts-Rettung von Rad-Daten).
 */
export function loadState(): AppState {
  const fallback = createEmptyState()
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (raw === null) return fallback

    const parsed: unknown = JSON.parse(raw)
    if (typeof parsed !== 'object' || parsed === null) return fallback

    const record = parsed as Record<string, unknown>

    // Unbekannte Version: Daten best-efforts retten, neu versionieren.
    const knownVersion = record.version === STATE_VERSION

    const draftRaw = record.draft
    let draft =
      draftRaw === null || draftRaw === undefined
        ? null
        : sanitizeWheel(draftRaw)

    const wheels = sanitizeWheels(record.wheels)

    // Ein "abgeschlossenes" Rad, das aus Versehen im Entwurfs-Slot liegt,
    // wandert in den Verlauf.
    if (draft !== null && draft.completedAt !== null) {
      wheels.push(draft)
      wheels.sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1))
      draft = null
    }

    return {
      version: STATE_VERSION,
      theme: sanitizeTheme(record.theme),
      wheels: knownVersion ? wheels : wheels, // (beide Pfade identisch – explicit)
      draft
    }
  } catch {
    return fallback
  }
}

/**
 * Schreibt den Zustand nach `localStorage`.
 * Fehler (z. B. Speicherplatz, privater Modus) bleiben still: die App
 * läuft im laufenden Speicher weiter, der Datenverlust betrifft nur das
 * nächste Neuladen.
 */
export function saveState(state: AppState): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state))
  } catch {
    /* bewusst still – siehe Kommentar oben */
  }
}

/** Löscht den gesamten gespeicherten Zustand (z. B. zum Zurücksetzen). */
export function clearState(): void {
  try {
    localStorage.removeItem(STORAGE_KEY)
  } catch {
    /* still */
  }
}

input.newString:
return {
  version: STATE_VERSION,
  theme: sanitizeTheme(record.theme),
  wheels,
  draft
}

input.oldString:
return {
  version: STATE_VERSION,
  theme: sanitizeTheme(record.theme),
  wheels: knownVersion ? wheels : wheels, // (beide Pfade identisch – explicit)
  draft
}

input.newString:
