// aktuellen Versionsnummer neu ablegen.

const draftRaw = record.draft

input.oldString:
// Unbekannte Version: Daten best-efforts retten, neu versionieren.
const knownVersion = record.version === STATE_VERSION

const draftRaw = record.draft

