import { useEffect, useState } from 'react'
import type { ThemePreference } from './types'

export type ResolvedTheme = 'light' | 'dark'

/** Wendet das Wunsch-Theme auf (System-Wunsch folgt der OS-Einstellung). */
export function resolveTheme(preference: ThemePreference, system: ResolvedTheme): ResolvedTheme {
  return preference === 'system' ? system : preference
}

/** Beobachtet die `prefers-color-scheme`-Einstellung des Systems. */
export function useSystemTheme(): ResolvedTheme {
  const [system, setSystem] = useState<ResolvedTheme>(() => {
    if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
      return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
    }
    return 'light'
  })

  useEffect(() => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return
    const query = window.matchMedia('(prefers-color-scheme: dark)')
    const onChange = (event: MediaQueryListEvent) => {
      setSystem(event.matches ? 'dark' : 'light')
    }
    setSystem(query.matches ? 'dark' : 'light')
    query.addEventListener('change', onChange)
    return () => query.removeEventListener('change', onChange)
  }, [])

  return system
}

/**
 * Trägt das aufgelöste Theme aus: `.dark`-Klasse auf <html> und
 * `theme-color`-Meta (der Browser-Chrome nimmt die Farbe darüber an).
 */
export function applyTheme(resolved: ResolvedTheme): void {
  if (typeof document === 'undefined') return
  document.documentElement.classList.toggle('dark', resolved === 'dark')

  const color = resolved === 'dark' ? '#131c1a' : '#f6f1e8'
  document
    .querySelectorAll('meta[name="theme-color"]')
    .forEach((element) => element.remove())
  const meta = document.createElement('meta')
  meta.name = 'theme-color'
  meta.content = color
  document.head.appendChild(meta)
}

import type { ReactElement } from 'react'

export const SEGMENT_COUNT = 8

interface FocusWheelSvgProps {
  /** Text im Zentrum des Rads (der Zielgedanke). */
  targetThought: string
  /**
   * Die acht Segmente (Index 0 = Segment 1, oben).
   * Ein leerer String bedeutet: Segment noch offen.
   */
  segments: string[]
  /** Seitliche Größe in CSS-px (Standard: flüssig über `100%` des Elternelements). */
  size?: number
  /** Segment-Nummern sichtbar machen (Standard: ja). */
  showNumbers?: boolean
  /** Zugänglicher Name, z. B. „Fokusrad: 5 von 8 Gedanken, Zentrum: …". */
  label?: string
  className?: string
}

/**
 * Rechnet einen Punkt in Polarkoordinaten um (0° = 12-Uhr-Position,
 * im Uhrzeigersinn). `degrees` ist relativ zur Mitte.
 */
function polarPoint(cx: number, cy: number, radius: number, degrees: number): [number, number] {
  const radians = ((degrees - 90) * Math.PI) / 180
  return [cx + radius * Math.cos(radians), cy + radius * Math.sin(radians)]
}

function format(value: number): string {
  return value.toFixed(2)
}

/**
 * Baut den Pfadeintrag eines Ringsegments (annular sector) mit
 * `gapDeg` Grad Lücke auf jeder Seite.
 */
function segmentPath(
  cx: number,
  cy: number,
  innerR: number,
  outerR: number,
  startDeg: number,
  endDeg: number
): string {
  const [ox1, oy1] = polarPoint(cx, cy, outerR, startDeg)
  const [ox2, oy2] = polarPoint(cx, cy, outerR, endDeg)
  const [ix2, iy2] = polarPoint(cx, cy, innerR, endDeg)
  const [ix1, iy1] = polarPoint(cx, cy, innerR, startDeg)
  const largeArc = endDeg - startDeg > 180 ? 1 : 0
  return [
    `M ${format(ox1)} ${format(oy1)}`,
    `A ${format(outerR)} ${format(outerR)} 0 ${largeArc} 1 ${format(ox2)} ${format(oy2)}`,
    `L ${format(ix2)} ${format(iy2)}`,
    `A ${format(innerR)} ${format(innerR)} 0 ${largeArc} 0 ${format(ix1)} ${format(iy1)}`,
    'Z'
  ].join(' ')
}

/**
 * Bricht Text grob um (Wort-für-Wort, zu lange Wörter hart getrennt),
 * bis `maxLines` erreicht ist; der letzte Zeilenabschnitt erhält ein „…".
 */
function wrapCenterText(text: string, maxChars: number, maxLines: number): string[] {
  const words = text.trim().split(/\s+/).filter((word) => word.length > 0)
  const lines: string[] = []
  let current = ''

  const breakHard = (chunk: string) => {
    if (current.length === 0) {
      current = chunk
    } else {
      lines.push(current)
      current = chunk
    }
  }

  for (const word of words) {
    let rest = word
    while (rest.length > maxChars) {
      breakHard(rest.slice(0, maxChars))
      rest = rest.slice(maxChars)
      if (lines.length >= maxLines) return lines
    }
    const candidate = current.length === 0 ? rest : `${current} ${rest}`
    if (candidate.length > maxChars && current.length > 0) {
      lines.push(current)
      current = rest
      if (lines.length >= maxLines) return lines
    } else {
      current = candidate
    }
  }
  if (current.length > 0) lines.push(current)

  if (lines.length > maxLines) {
    const kept = lines.slice(0, maxLines)
    const last = kept[kept.length - 1]
    kept[kept.length - 1] =
      last.length > maxChars ? last.slice(0, Math.max(1, maxChars - 1)) + '…' : last
    return kept
  }
  return lines
}

/**
 * Das SVG-Fokusrad: acht Kreissegmente rund um ein Zentrum, in dem der
 * Zielgedanke steht. Gefüllte Segmente (nicht leerer Satz) nehmen die
 * Farbe des jeweiligen Radschritts (`--wheel-1` … `--wheel-8`) an und
 * färb sich weich ein (Transition in `index.css`).
 */
export function FocusWheelSvg({
  targetThought,
  segments,
  size,
  showNumbers = true,
  label,
  className
}: FocusWheelSvgProps): ReactElement {
  const cx = 100
  const cy = 100
  const outerR = 92
  const innerR = 54
  const centerR = 47
  const gapDeg = 2.8
  const perSegment = 360 / SEGMENT_COUNT

  const centerText = targetThought.trim().length > 0
    ? wrapCenterText(targetThought.trim(), 9, 4)
    : ['dein', 'Zielgefühl']

  const filled = segments.filter((s) => s.trim().length > 0).length
  const ariaLabel =
    label ??
    `Fokusrad: ${filled} von ${SEGMENT_COUNT} Gedanken, Zielgedanke: ${targetThought || 'offen'}`

  return (
    <svg
      viewBox="0 0 200 200"
      role="img"
      aria-label={ariaLabel}
      className={className}
      style={size !== undefined ? { width: size, height: size } : undefined}
    >
      {/* Ruhiger Rahmenring */}
      <circle cx={cx} cy={cy} r={98} fill="none" stroke="var(--line)" strokeWidth={1} />

      {/* Die acht Segmente */}
      {segments.slice(0, SEGMENT_COUNT).map((text, index) => {
        const start = index * perSegment + gapDeg / 2
        const end = (index + 1) * perSegment - gapDeg / 2
        const isFilled = text.trim().length > 0
        const [nx, ny] = polarPoint(cx, cy, (innerR + outerR) / 2 + 2, index * perSegment + perSegment / 2)
        return (
          <g key={index}>
            <path
              d={segmentPath(cx, cy, innerR, outerR, start, end)}
              className="wheel-segment"
              fill={`var(--wheel-${index + 1})`}
              opacity={isFilled ? 1 : 0.55}
            />
            {showNumbers && (
              <text
                x={nx}
                y={ny}
                textAnchor="middle"
                dominantBaseline="central"
                fontSize={11}
                fontWeight={600}
                fill={isFilled ? 'var(--seg-num)' : 'var(--ink-3)'}
                className="wheel-segment"
                style={{ pointerEvents: 'none' }}
              >
                {index + 1}
              </text>
            )}
          </g>
        )
      })}

      {/* Zentrum mit Zielgedanken */}
      <circle
        className="wheel-center"
        cx={cx}
        cy={cy}
        r={centerR}
        fill="var(--surface)"
        stroke="var(--line)"
        strokeWidth={1.5}
      />
      {centerText.map((line, index) => (
        <text
          key={index}
          x={cx}
          y={cy + (index - (centerText.length - 1) / 2) * 13}
          textAnchor="middle"
          dominantBaseline="central"
          fontSize={10.5}
          fontWeight={index === 0 && centerText.length <= 2 ? 600 : 500}
          fill="var(--center-ink)"
        >
          {line}
        </text>
      ))}
    </svg>
  )
}

export { wrapCenterText }

import type { ReactElement } from 'react'
import { MOOD_LABELS, clampMood } from '../types'

interface MoodScaleProps {
  value: number
  onChange: (mood: number) => void
  /** Label für Screenreader, z. B. „Start-Stimmung". */
  label: string
  /** Das beschreibende Wort unter der Skala zeigen (Standard: ja). */
  showCaption?: boolean
  className?: string
}

const MOODS = [1, 2, 3, 4, 5] as const

/**
 * Fünf-Punkte-Stimmungsskala: fünf 44-px-Touch-Ziele, die sich bei
 * Auswahl mit ihrer eigenen Stimmungsfarbe füllen (CSS-Variablen
 * `--mood-1` … `--mood-5`).
 */
export function MoodScale({
  value,
  onChange,
  label,
  showCaption = true,
  className
}: MoodScaleProps): ReactElement {
  const safe = clampMood(value)
  return (
    <div className={className}>
      <div
        role="group"
        aria-label={label}
        className="grid grid-cols-5 gap-2"
      >
        {MOODS.map((mood) => {
          const selected = mood === safe
          return (
            <button
              key={mood}
              type="button"
              aria-pressed={selected}
              aria-label={`${label}: ${mood} von 5 (${MOOD_LABELS[mood - 1]})`}
              onClick={() => onChange(mood)}
              className="press chip flex h-11 w-11 items-center justify-center rounded-full border text-[16px] font-semibold"
              style={{
                backgroundColor: selected
                  ? `var(--mood-${mood})`
                  : 'var(--surface-2)',
                color: selected
                  ? `var(--mood-num-${mood})`
                  : 'var(--ink-2)',
                borderColor: selected ? 'transparent' : 'var(--line)',
                boxShadow: selected
                  ? '0 8px 18px -8px rgb(var(--shadow) / 0.6)'
                  : undefined
              }}
            >
              {mood}
            </button>
          )
        })}
      </div>
      {showCaption && (
        <p
          aria-live="polite"
          className="mt-3 text-center text-[15px] font-medium"
          style={{ color: 'var(--ink-2)' }}
        >
          {MOOD_LABELS[safe - 1]}
        </p>
      )}
    </div>
  )
}

import type { ReactElement } from 'react'
import { Moon, Monitor, Sun } from 'lucide-react'
import type { ThemePreference } from '../types'

interface ThemeToggleProps {
  value: ThemePreference
  onChange: (preference: ThemePreference) => void
  className?: string
}

const OPTIONS: Array<{
  id: ThemePreference
  label: string
  Icon: typeof Sun
}> = [
  { id: 'light', label: 'Helles Design', Icon: Sun },
  { id: 'dark', label: 'Dunkles Design', Icon: Moon },
  { id: 'system', label: 'Systemdesign', Icon: Monitor }
]

/**
 * Sichtbarer Theme-Schalter mit drei Zuständen: Licht / Dunkel / System.
 * Die Auswahl wird von der App in `localStorage` abgelegt.
 */
export function ThemeToggle({ value, onChange, className }: ThemeToggleProps): ReactElement {
  return (
    <div
      role="group"
      aria-label="Farbschema"
      className={`flex items-center rounded-full border p-1 ${className ?? ''}`}
      style={{ backgroundColor: 'var(--surface)', borderColor: 'var(--line)' }}
    >
      {OPTIONS.map(({ id, label, Icon }) => {
        const selected = value === id
        return (
          <button
            key={id}
            type="button"
            aria-pressed={selected}
            aria-label={label}
            title={label}
            onClick={() => onChange(id)}
            className="press chip flex h-9 w-9 items-center justify-center rounded-full"
            style={{
              backgroundColor: selected ? 'var(--accent)' : 'transparent',
              color: selected ? 'var(--accent-ink)' : 'var(--ink-2)'
            }}
          >
            <Icon size={18} strokeWidth={2} aria-hidden />
          </button>
        )
      })}
    </div>
  )
}

