import type { ReactElement } from 'react'

interface WheelGlyphProps {
  size?: number
  className?: string
}

/**
 * Kompaktes Fokusrad-Emblem für Header und Navigation:
 * acht Segmente rund um ein Zentrum, in den Radfarben der App.
 */
export function WheelGlyph({ size = 20, className }: WheelGlyphProps): ReactElement {
  const segments = [0, 1, 2, 3, 4, 5, 6, 7].map((i) => {
    const start = i * 45 + 2
    const end = (i + 1) * 45 - 2
    const toPoint = (r: number, deg: number): string => {
      const rad = ((deg - 90) * Math.PI) / 180
      return `${(12 + r * Math.cos(rad)).toFixed(2)} ${(12 + r * Math.sin(rad)).toFixed(2)}`
    }
    return (
      <path
        key={i}
        d={`M ${toPoint(10, start)} A 10 10 0 0 1 ${toPoint(10, end)} L ${toPoint(5, end)} A 5 5 0 0 0 ${toPoint(5, start)} Z`}
        fill={`var(--wheel-${i + 1})`}
      />
    )
  })

  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      className={className}
      aria-hidden
    >
      {segments}
      <circle cx={12} cy={12} r={4.2} fill="var(--surface)" stroke="var(--line)" strokeWidth={0.8} />
    </svg>
  )
}

import type { ReactElement } from 'react'
import { History } from 'lucide-react'
import { WheelGlyph } from './WheelGlyph'

export type MainTab = 'home' | 'archive'

interface BottomNavProps {
  active: MainTab
  onNavigate: (tab: MainTab) => void
}

/**
 * Untere Tab-Navigation (Fokusrad / Verlauf) – bewusst in der
 * Thumb-Zone, 56 px hoch plus Safe-Area-Unterrand, zwei große Ziele.
 */
export function BottomNav({ active, onNavigate }: BottomNavProps): ReactElement {
  const base =
    'press tab flex min-h-14 flex-1 flex-col items-center justify-center gap-1 text-[12px] font-semibold'

  return (
    <nav
      aria-label="Hauptnavigation"
      className="safe-bottom fixed inset-x-0 bottom-0 z-40 mx-auto w-full max-w-md"
    >
      <div
        className="grid grid-cols-2 border-t"
        style={{
          backgroundColor: 'color-mix(in srgb, var(--surface) 92%, transparent)',
          borderColor: 'var(--line)',
          backdropFilter: 'blur(12px)',
          WebkitBackdropFilter: 'blur(12px)'
        }}
      >
        <button
          type="button"
          aria-current={active === 'home' ? 'page' : undefined}
          onClick={() => onNavigate('home')}
          className={base}
          style={{ color: active === 'home' ? 'var(--accent)' : 'var(--ink-2)' }}
        >
          <WheelGlyph size={22} />
          Fokusrad
        </button>
        <button
          type="button"
          aria-current={active === 'archive' ? 'page' : undefined}
          onClick={() => onNavigate('archive')}
          className={base}
          style={{ color: active === 'archive' ? 'var(--accent)' : 'var(--ink-2)' }}
        >
          <History size={20} strokeWidth={2.2} aria-hidden />
          Verlauf
        </button>
      </div>
    </nav>
  )
}

import { useId, useRef, useState } from 'react'
import type { FormEvent, ReactElement } from 'react'
import { ArrowRight } from 'lucide-react'
import { MoodScale } from '../components/MoodScale'

interface NewWheelViewProps {
  onStart: (startThought: string, targetThought: string, startMood: number) => void
}

/**
 * Eingang einer neuen Session: Ausgangsgedanke, Zielgedanke und
 * Start-Stimmung. Der Start-Button sitzt unten in der Thumb-Zone.
 */
export function NewWheelView({ onStart }: NewWheelViewProps): ReactElement {
  const formId = useId()
  const [startThought, setStartThought] = useState('')
  const [targetThought, setTargetThought] = useState('')
  const [startMood, setStartMood] = useState(3)
  const startFieldRef = useRef<HTMLTextAreaElement>(null)

  const ready = startThought.trim().length > 0 && targetThought.trim().length > 0

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!ready) return
    onStart(startThought.trim(), targetThought.trim(), startMood)
    setStartThought('')
    setTargetThought('')
    setStartMood(3)
  }

  return (
    <form id={formId} onSubmit={handleSubmit} className="flex flex-col gap-4">
      <div className="card p-5">
        <label
          htmlFor={`${formId}-start`}
          className="mb-2 block text-[15px] font-semibold"
          style={{ color: 'var(--ink)' }}
        >
          Ausgangsgedanke
        </label>
        <p className="mb-3 text-[14px]" style={{ color: 'var(--ink-2)' }}>
          Was stört oder drückt gerade? Ein Gedanke, eine Sorge, ein Gefühl.
        </p>
        <textarea
          id={`${formId}-start`}
          ref={startFieldRef}
          className="field resize-none"
          rows={3}
          maxLength={1000}
          placeholder="z. B. „Ich habe das Gefühl, alles gleichzeitig machen zu müssen.“"
          value={startThought}
          onChange={(event) => setStartThought(event.target.value)}
        />
      </div>

      <div className="card p-5">
        <label
          htmlFor={`${formId}-target`}
          className="mb-2 block text-[15px] font-semibold"
          style={{ color: 'var(--ink)' }}
        >
          Zielgedanke
        </label>
        <p className="mb-3 text-[14px]" style={{ color: 'var(--ink-2)' }}>
          Wie möchtest du dich stattdessen fühlen? Er steht im Zentrum deines Rads.
        </p>
        <textarea
          id={`${formId}-target`}
          className="field resize-none"
          rows={2}
          maxLength={500}
          placeholder="z. B. „Ich darf nach und nach.“"
          value={targetThought}
          onChange={(event) => setTargetThought(event.target.value)}
        />
      </div>

      <div className="card p-5">
        <span
          className="mb-1 block text-[15px] font-semibold"
          style={{ color: 'var(--ink)' }}
        >
          Start-Stimmung
        </span>
        <p className="mb-4 text-[14px]" style={{ color: 'var(--ink-2)' }}>
          Wo stehst du gerade – von 1 (belastet) bis 5 (ruhig)?
        </p>
        <MoodScale value={startMood} onChange={setStartMood} label="Start-Stimmung" />
      </div>

      <div className="safe-bottom sticky bottom-0 -mx-4 px-4 pb-4 pt-2">
        <div className="card p-4">
          <button
            type="submit"
            disabled={!ready}
            className="btn-primary press w-full"
          >
            Fokusrad starten
            <ArrowRight size={18} aria-hidden />
          </button>
          <p className="mt-3 text-center text-[13px]" style={{ color: 'var(--ink-3)' }}>
            Dauer: 5 Minuten · alles bleibt auf diesem Gerät
          </p>
        </div>
      </div>
    </form>
  )
}

