import type { ReactElement } from 'react'
import { ArrowRight } from 'lucide-react'
import { clampMood } from '../types'

interface MoodShiftProps {
  start: number
  end: number | null
  /** `lg` für den Abschlussbildschirm, `sm` für Listenzeilen. */
  size?: 'sm' | 'lg'
}

function deltaLabel(delta: number): string {
  if (delta > 0) return `+${delta} – ein spürbarer Shift`
  if (delta < 0) return `${delta} – ein schwererer Tag, danke für die Ehrlichkeit`
  return 'geblieben – auch das zählt'
}

/**
 * Visualisiert den Stimmungs-Shift: Start- und End-Punkt in ihren
 * Stimmungsfarben, verbunden durch eine Pfeil-Richtung.
 */
export function MoodShift({ start, end, size = 'sm' }: MoodShiftProps): ReactElement | null {
  if (end === null) return null
  const s = clampMood(start)
  const e = clampMood(end)

  if (size === 'sm') {
    return (
      <span className="inline-flex items-center gap-1.5 text-[14px] font-semibold tabular-nums">
        <span
          aria-hidden
          className="inline-block h-2.5 w-2.5 rounded-full"
          style={{ backgroundColor: `var(--mood-${s})` }}
        />
        {s}
        <ArrowRight size={13} className="shrink-0" style={{ color: 'var(--ink-3)' }} aria-hidden />
        <span
          aria-hidden
          className="inline-block h-2.5 w-2.5 rounded-full"
          style={{ backgroundColor: `var(--mood-${e})` }}
        />
        {e}
      </span>
    )
  }

  return (
    <div className="flex items-center justify-center gap-4" aria-live="polite">
      <span
        className="pop-in flex h-16 w-16 items-center justify-center rounded-full text-[24px] font-bold"
        style={{ backgroundColor: `var(--mood-${s})`, color: `var(--mood-num-${s})` }}
      >
        {s}
      </span>
      <ArrowRight size={26} style={{ color: 'var(--ink-2)' }} aria-hidden />
      <span
        className="pop-in flex h-16 w-16 items-center justify-center rounded-full text-[24px] font-bold"
        style={{
          backgroundColor: `var(--mood-${e})`,
          color: `var(--mood-num-${e})`,
          animationDelay: '140ms',
          boxShadow: '0 14px 30px -12px rgb(var(--shadow) / 0.55)'
        }}
      >
        {e}
      </span>
    </div>
  )
}

/** Kurz-Unterschrift zum Shift-Delta (nur für abgeschlossene Räder). */
export function moodDeltaLabel(start: number, end: number | null): string | null {
  if (end === null) return null
  return deltaLabel(clampMood(end) - clampMood(start))
}

const listFormatter = new Intl.DateTimeFormat('de-DE', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric'
})

const fullFormatter = new Intl.DateTimeFormat('de-DE', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
})

/** „16.11.2026" – für Listenzeilen. */
export function formatListDate(iso: string): string {
  const date = new Date(iso)
  if (Number.isNaN(date.getTime())) return ''
  return listFormatter.format(date)
}

/** „16.11.2026, 20:12 Uhr" – für Detailansichten. */
export function formatFullDate(iso: string): string {
  const date = new Date(iso)
  if (Number.isNaN(date.getTime())) return ''
  return `${fullFormatter.format(date)} Uhr`
}

import type { ReactElement } from 'react'
import { ChevronRight } from 'lucide-react'
import type { FocusWheel } from '../types'
import { FocusWheelSvg } from '../components/FocusWheelSvg'
import { MoodShift } from '../components/MoodShift'
import { WheelGlyph } from '../components/WheelGlyph'
import { formatListDate } from '../format'

interface ArchiveViewProps {
  wheels: FocusWheel[]
  onOpenWheel: (id: string) => void
  onStartNew: () => void
}

/**
 * Verlauf aller abgeschlossenen Fokusräder: Datum, Ausgangs- und
 * Zielgedanke sowie der Stimmungs-Shift. Antippen öffnet die Detailansicht.
 */
export function ArchiveView({ wheels, onOpenWheel, onStartNew }: ArchiveViewProps): ReactElement {
  if (wheels.length === 0) {
    return (
      <section className="card rise-in flex flex-col items-center gap-4 p-8 text-center">
        <div
          className="flex h-24 w-24 items-center justify-center rounded-full"
          style={{ backgroundColor: 'color-mix(in srgb, var(--accent) 10%, transparent)' }}
        >
          <WheelGlyph size={52} />
        </div>
        <div>
          <h2 className="text-[18px] font-bold" style={{ color: 'var(--ink)' }}>
            Noch keine abgeschlossenen Fokusräder
          </h2>
          <p className="mt-2 text-[15px] leading-relaxed" style={{ color: 'var(--ink-2)' }}>
            Wenn du dein erstes Rad abschließt, findest du es hier – mit Datum, Gedanken und
            Stimmungs-Shift.
          </p>
        </div>
        <button type="button" onClick={onStartNew} className="btn-primary press w-full">
          Ersten Fokusrad starten
        </button>
      </section>
    )
  }

  return (
    <div className="flex flex-col gap-3">
      {wheels.map((wheel) => {
        const date = wheel.completedAt !== null ? wheel.completedAt : wheel.createdAt
        return (
          <button
            key={wheel.id}
            type="button"
            onClick={() => onOpenWheel(wheel.id)}
            aria-label={`Fokusrad vom ${formatListDate(date)} öffnen`}
            className="card press flex w-full items-center gap-3 p-4 text-left"
          >
            <div className="w-14 shrink-0">
              <FocusWheelSvg
                size={56}
                targetThought={wheel.targetThought}
                segments={wheel.segments}
                showNumbers={false}
                label=""
              />
            </div>
            <div className="min-w-0 flex-1">
              <p className="text-[12px] tabular-nums" style={{ color: 'var(--ink-3)' }}>
                {formatListDate(date)}
              </p>
              <p
                className="mt-1 line-clamp-2 text-[15px] font-medium leading-snug"
                style={{ color: 'var(--ink)' }}
              >
                {wheel.startThought.length > 0 ? wheel.startThought : 'Ohne Ausgangsgedanken'}
              </p>
              <div className="mt-2 flex items-center gap-3">
                <MoodShift start={wheel.startMood} end={wheel.endMood} />
                {wheel.targetThought.length > 0 && (
                  <span className="truncate text-[13px]" style={{ color: 'var(--ink-2)' }}>
                    → {wheel.targetThought}
                  </span>
                )}
              </div>
            </div>
            <ChevronRight size={20} className="shrink-0" style={{ color: 'var(--ink-3)' }} aria-hidden />
          </button>
        )
      })}
    </div>
  )
}

import { useCallback, useEffect, useState } from 'react'
import type { ReactElement } from 'react'
import { ArrowLeft } from 'lucide-react'
import type { AppState, FocusWheel, ThemePreference } from './types'
import { clampMood, createDraft } from './types'
import { loadState, saveState } from './storage'
import { applyTheme, resolveTheme, useSystemTheme } from './theme'
import { ThemeToggle } from './components/ThemeToggle'
import { BottomNav, type MainTab } from './components/BottomNav'
import { WheelGlyph } from './components/WheelGlyph'
import { HomeView } from './views/HomeView'
import { SessionView } from './views/SessionView'
import { CompleteView } from './views/CompleteView'
import { ArchiveView } from './views/ArchiveView'
import { DetailView } from './views/DetailView'

type View =
  | { name: 'home' }
  | { name: 'active' }
  | { name: 'complete'; wheelId: string }
  | { name: 'archive' }
  | { name: 'detail'; wheelId: string }

/**
 * Fokusrad – App-Rumpf: hält den App-Zustand (versioniert in
 * `localStorage`), die Themenauswahl und die Ansichtsführung.
 */
export default function App(): ReactElement {
  const [state, setState] = useState<AppState>(() => loadState())
  const [view, setView] = useState<View>({ name: 'home' })

  // Persistenz: jeder Zustandswunsch wird (still) gespeichert.
  useEffect(() => {
    saveState(state)
  }, [state])

  // Theme: Wunsch aus dem Zustand + System-Einstellung.
  const systemTheme = useSystemTheme()
  const resolved = resolveTheme(state.theme, systemTheme)
  useEffect(() => {
    applyTheme(resolved)
  }, [resolved])

  const setThemePreference = useCallback((theme: ThemePreference) => {
    setState((current) => ({ ...current, theme }))
  }, [])

  /* ---------------- Session-Lebenszyklus ---------------- */

  const startWheel = useCallback(
    (startThought: string, targetThought: string, startMood: number) => {
      setState((current) => ({
        ...current,
        draft: createDraft(startThought, targetThought, startMood)
      }))
      setView({ name: 'active' })
    },
    []
  )

  const saveSegment = useCallback((index: number, text: string) => {
    setState((current) => {
      if (current.draft === null) return current
      const segments = [...current.draft.segments]
      segments[index] = text
      return { ...current, draft: { ...current.draft, segments } }
    })
  }, [])

  /** Schließt das Rad mit der gewählten End-Stimmung ab. */
  const commitWheel = useCallback((endMood: number) => {
    setState((current) => {
      if (current.draft === null) return current
      const completed: FocusWheel = {
        ...current.draft,
        endMood: clampMood(endMood),
        completedAt: new Date().toISOString()
      }
      return {
        ...current,
        draft: null,
        wheels: [completed, ...current.wheels]
      }
    })
  }, [])

  const discardDraft = useCallback(() => {
    setState((current) => ({ ...current, draft: null }))
    setView({ name: 'home' })
  }, [])

  const deleteWheel = useCallback((id: string) => {
    setState((current) => ({
      ...current,
      wheels: current.wheels.filter((wheel) => wheel.id !== id)
    }))
    setView({ name: 'archive' })
  }, [])

  /* ---------------- Abgeleitete Daten ---------------- */

  const draft = state.draft
  const detailWheel =
    view.name === 'detail' || view.name === 'complete'
      ? (state.wheels.find((wheel) => wheel.id === view.wheelId) ??
        (view.name === 'complete' ? null : null)) ??
        null
      : null

  const navVisible = view.name === 'home' || view.name === 'archive' || view.name === 'detail'

  const headerVisible = view.name !== 'active'

  /* ---------------- Ansichtsaufbau ---------------- */

  let viewContent: ReactElement
  switch (view.name) {
    case 'home':
      viewContent = (
        <HomeView
          draft={draft}
          wheels={state.wheels}
          onStart={startWheel}
          onContinue={() => setView({ name: 'active' })}
          onDiscardDraft={discardDraft}
          onOpenArchive={() => setView({ name: 'archive' })}
        />
      )
      break
    case 'active':
      viewContent =
        draft !== null ? (
          <SessionView
            draft={draft}
            onSaveSegment={saveSegment}
            onComplete={() => setView({ name: 'complete', wheelId: draft.id })}
            onBack={() => setView({ name: 'home' })}
            onDiscard={discardDraft}
          />
        ) : (
          <HomeView
            draft={null}
            wheels={state.wheels}
            onStart={startWheel}
            onContinue={() => undefined}
            onDiscardDraft={discardDraft}
            onOpenArchive={() => setView({ name: 'archive' })}
          />
        )
      break
    case 'complete':
      viewContent =
        detailWheel !== null ? (
          <CompleteView
            wheel={detailWheel}
            onGoToArchive={() => setView({ name: 'archive' })}
            onNewWheel={() => setView({ name: 'home' })}
          />
        ) : (
          <ArchiveView
            wheels={state.wheels}
            onOpenWheel={(id) => setView({ name: 'detail', wheelId: id })}
            onStartNew={() => setView({ name: 'home' })}
          />
        )
      break
    case 'archive':
      viewContent = (
        <ArchiveView
          wheels={state.wheels}
          onOpenWheel={(id) => setView({ name: 'detail', wheelId: id })}
          onStartNew={() => setView({ name: 'home' })}
        />
      )
      break
    case 'detail':
      viewContent =
        detailWheel !== null ? (
          <DetailView
            wheel={detailWheel}
            onBack={() => setView({ name: 'archive' })}
            onDelete={deleteWheel}
          />
        ) : (
          <ArchiveView
            wheels={state.wheels}
            onOpenWheel={(id) => setView({ name: 'detail', wheelId: id })}
            onStartNew={() => setView({ name: 'home' })}
          />
        )
      break
  }

  const showCompleteAsk = view.name === 'complete' && detailWheel === null

  return (
    <div className="app-shell mx-auto flex w-full max-w-md flex-col" style={{ minHeight: '100dvh' }}>
      {headerVisible && (
        <header
          className="safe-top sticky top-0 z-30"
          style={{
            backgroundColor: 'color-mix(in srgb, var(--bg) 85%, transparent)',
            backdropFilter: 'blur(12px)',
            WebkitBackdropFilter: 'blur(12px)',
            borderBottom: '1px solid color-mix(in srgb, var(--line) 60%, transparent)'
          }}
        >
          <div className="mx-auto flex max-w-md items-center justify-between gap-3 px-4 py-3">
            <div className="flex min-w-0 items-center gap-2.5">
              {view.name === 'detail' || showCompleteAsk ? (
                <button
                  type="button"
                  onClick={() => setView(view.name === 'detail' ? { name: 'archive' } : { name: 'home' })}
                  aria-label="Zurück"
                  className="press chip flex h-11 w-11 shrink-0 items-center justify-center rounded-full border"
                  style={{
                    backgroundColor: 'var(--surface)',
                    borderColor: 'var(--line)',
                    color: 'var(--ink)'
                  }}
                >
                  <ArrowLeft size={20} aria-hidden />
                </button>
              ) : (
                <WheelGlyph size={26} className="shrink-0" />
              )}
              <span className="truncate text-[17px] font-bold" style={{ color: 'var(--ink)' }}>
