/* End-to-End-Prüfung der Fokusrad-App gegen `npm run preview`. */
import { chromium } from 'playwright-core'

const BASE = 'http://localhost:4173/'
const results = []
function check(name, ok, extra = '') {
  results.push({ name, ok: Boolean(ok), extra })
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra ? `  (${extra})` : ''}`)
}

const browser = await chromium.launch({
  channel: 'chrome',
  headless: true,
  args: ['--no-first-run', '--no-default-browser-check']
})
try {
  const context = await browser.newContext({
    viewport: { width: 375, height: 812 },
    userAgent:
      'Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1'
  })
  const page = await context.newPage()
  page.on('pageerror', (err) => console.log('PAGE-ERROR:', err.message))
  const consoleErrors = []
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text())
  })

  /* ---------- Erstladung / Leerzustand ---------- */
  await page.goto(BASE, { waitUntil: 'networkidle' })
  await page.waitForTimeout(400)

  check('Titel „Fokusrad“', await page.title() === 'Fokusrad', await page.title())

  const bodyBg = await page.evaluate(() => getComputedStyle(document.body).backgroundColor)
  check('Tailwind-Styles greifen (Body-Hintergrund Morgenfluss-Sand)', bodyBg === 'rgb(246, 241, 232)', bodyBg)

  const styleCount = await page.locator('link[rel="stylesheet"]').count()
  check('Stylesheet-Link vorhanden', styleCount > 0, `${styleCount} Links`)

  const cssLoaded = await page.evaluate(async () => {
    for (const link of document.querySelectorAll('link[rel="stylesheet"]')) {
      try {
        const res = await fetch(link.href)
        if (!res.ok) return false
        const text = await res.text()
        if (text.length < 1000) return false
      } catch {
        return false
      }
    }
    return true
  })
  check('Stylesheet-Auslieferung > 1 KB (Tailwind gebaut)', cssLoaded)

  const manifest = await page.evaluate(async () => {
    const link = document.querySelector('link[rel="manifest"]')
    if (!link) return null
    const res = await fetch(link.href)
    return { ok: res.ok, json: await res.json().catch(() => null) }
  })
  check('Manifest geladen', manifest?.ok === true, manifest?.json?.name ?? 'n/a')
  const iconEntries = manifest?.json?.icons ?? []
  check(
    'Manifest-Icons 192+512 (any) und maskable 512',
    iconEntries.some((i) => i.sizes === '192x192') &&
      iconEntries.some((i) => i.sizes === '512x512' && (i.purpose ?? '').includes('any')) &&
      iconEntries.some((i) => i.sizes === '512x512' && (i.purpose ?? '').includes('maskable')),
    JSON.stringify(iconEntries.map((i) => `${i.sizes}:${i.purpose}`))
  )

  const pngSizes = await page.evaluate(async () => {
    const out = {}
    for (const path of ['/icons/icon-192.png', '/icons/icon-512.png', '/apple-touch-icon.png', '/favicon.svg']) {
      const res = await fetch(path)
      out[path] = res.ok ? (await res.blob()).size : -1
    }
    return out
  })
  check(
    'Icons > 0 Byte ausgeliefert',
    Object.values(pngSizes).every((n) => n > 0),
    JSON.stringify(pngSizes)
  )

  const emptyState = await page.getByText('Hallo. Nimm dir fünf Minuten.').count()
  check('Leerzustand mit Begrüßung sichtbar', emptyState === 1)

  const startButton = page.getByRole('button', { name: /Erster Fokusrad starten/ })
  check('Sofort klickbarer Start-Button im Leerzustand', (await startButton.count()) === 1)

  /* Service Worker */
  let swRegistered = false
  for (let i = 0; i < 20 && !swRegistered; i++) {
    swRegistered = await page.evaluate(async () => {
      if (!('serviceWorker' in navigator)) return false
      const reg = await navigator.serviceWorker.getRegistration()
      return Boolean(reg)
    })
    if (!swRegistered) await page.waitForTimeout(500)
  }
  check('Service Worker registriert (PWA offline-fähig)', swRegistered)

  const swScript = await page.evaluate(async () => {
    const res = await fetch('/sw.js')
    return res.ok ? res.status : -1
  })
  check('sw.js ausgeliefert', swScript === 200, `HTTP ${swScript}`)

  await page.screenshot({ path: 'shots/01-leerzustand.png' })

  /* ---------- Neues Fokusrad starten ---------- */
  await startButton.click()
  await page.waitForTimeout(350)
  await page.screenshot({ path: 'shots/02-formular.png' })

  const submitDisabled = await page
    .getByRole('button', { name: /Fokusrad starten/ })
    .first()
    .isDisabled()
  check('Start-Button des Formulars initial deaktiviert', submitDisabled)

  const startField = page.getByRole('textbox', { name: /Ausgangsgedanke/ })
  await startField.fill('Ich habe das Gefühl, alles gleichzeitig machen zu müssen.')
  const targetField = page.getByRole('textbox', { name: /Zielgedanke/ })
  await targetField.fill('Ich darf nach und nach.')

  const enabledNow = await page
    .getByRole('button', { name: /Fokusrad starten/ })
    .first()
    .isDisabled()
  check('Start-Button aktiv, sobald beide Felder gefüllt', enabledNow === false)

  // Start-Stimmung 2 wählen
  await page.getByRole('button', { name: /Start-Stimmung: 2 von 5/ }).click()
  const moodCaption = await page.getByText('angespannt').count()
  check('Stimmungs-Label wechselt (1 → 2 = „angespannt“)', moodCaption >= 1)

  await page
    .getByRole('button', { name: /Fokusrad starten/ })
    .first()
    .click()
  await page.waitForTimeout(400)
  await page.screenshot({ path: 'shots/03-session.png' })

  const progressText = await page.getByText(/0 von 8 Gedanken/).count()
  check('Session: Fortschritt „0 von 8 Gedanken“', progressText === 1)

  const svgCount = await page.locator('svg[role="img"]').count()
  check('SVG-Fokusrad in der Session sichtbar', svgCount >= 1, `${svgCount} SVGs`)

  const wheelFilled0 = await page.evaluate(() => {
