    return Array.from(paths).filter((p) => p.getAttribute('opacity') !== '0.55').length
  })
  check('Zuerst kein Segment gefüllt', wheelFilled0 === 0, `${wheelFilled0} gefüllt`)

  /* ---------- Acht Segmente eintragen ---------- */
  for (let i = 0; i < 8; i++) {
    const input = page.locator('#segment-input')
    await input.click()
