  })
  check('Zielgedanke im Rad-Zentrum', centerText.includes('Ich darf'), centerText)

  const listSentences = await page.locator('text=Entlastender Satz 8').count()
  check('Eingetragene Sätze unter dem Rad sichtbar', listSentences >= 1)

  const completeBtn = page.getByRole('button', { name: /Fokusrad abschließen/ })
  check('Abschluss-Button erscheint bei 8/8', (await completeBtn.count()) === 1)

  const draftStored = await page.evaluate(() => {
    const raw = localStorage.getItem('fokusrad:v1:state')
    if (!raw) return null
    const state = JSON.parse(raw)
    return { version: state.version, draft: state.draft, seg1: state.draft?.segments[0] }
  })
  check(
    'Entwurf wird in localStorage zwischengespeichert (versioniert)',
    draftStored?.version === 1 && draftStored?.draft !== null && draftStored?.seg1 === 'Entlastender Satz 1',
    `version=${draftStored?.version} seg1=${draftStored?.seg1}`
  )

  /* ---------- Reload-Mittendrin: Entwurf bleibt erhalten ---------- */
  await page.reload({ waitUntil: 'networkidle' })
  await page.waitForTimeout(400)
  const continueCard = await page.getByRole('button', { name: /Session fortsetzen/ }).count()
  check('Nach Reload: „Weitermachen“-Karte auf Startseite', continueCard === 1)
  await page.getByRole('button', { name: /Session fortsetzen/ }).click()
  await page.waitForTimeout(400)
  const preserved = await page.getByText(/8 von 8 Gedanken/).count()
  check('Session nach Reload intakt (8/8, Sätze erhalten)', preserved === 1)

  /* ---------- Abschluss: End-Stimmung ---------- */
  await page.getByRole('button', { name: /Fokusrad abschließen/ }).click()
  await page.waitForTimeout(400)
  await page.screenshot({ path: 'shots/04-abschluss.png' })

  const askPhase = await page.getByText(/Alle acht Gedanken stehen im Rad/).count()
  check('Abschluss fragt End-Stimmung ab', askPhase === 1)

  await page.getByRole('button', { name: /End-Stimmung: 4 von 5/ }).click()
  await page.getByRole('button', { name: /Fokusrad abschließen/ }).click()
  await page.waitForTimeout(500)
  await page.screenshot({ path: 'shots/05-shift.png' })

  const shiftLine = await page.getByText(/Stimmung: 2 → 4/).count()
  check('Stimmungs-Shift „Stimmung: 2 → 4“ hervorgehoben', shiftLine === 1)

