  const detailFull = await page.getByText('Entlastender Satz 8').count()
  check('Detailansicht zeigt alle acht Sätze', detailFull >= 1)
  const detailDate = await page.getByText(/Uhr$/).count()
  check('Detailansicht zeigt Datum/Zeit', detailDate >= 1)

  /* ---------- Löschen mit Bestätigung ---------- */
  await page.getByRole('button', { name: /Eintrag löschen/ }).click()
  const confirmBtn = page.getByRole('button', { name: /Ja, löschen/ })
