  check('Nach Löschung: Archiv-Leerzustand zurück', archiveEmptyAgain === 1)
  const wheelsAfterDelete = await page.evaluate(() => JSON.parse(localStorage.getItem('fokusrad:v1:state') ?? '{}').wheels.length)
  check('LocalStorage: 0 Räder nach Löschung', wheelsAfterDelete === 0)

  /* ---------- Dark Mode ---------- */
